public class Main {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int v) { val = v; }
    }

    static boolean hasPathSum(TreeNode root, long target) {
        // Write your solution here
        return false;
    }

    static TreeNode build(String[] tokens, int len) {
        if (len == 0 || tokens[0].equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(tokens[0]));
        ArrayDeque<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < len) {
            TreeNode node = q.poll();
            if (i < len && !tokens[i].equals("null")) {
                node.left = new TreeNode(Integer.parseInt(tokens[i]));
                q.add(node.left);
            }
            i++;
            if (i < len && !tokens[i].equals("null")) {
                node.right = new TreeNode(Integer.parseInt(tokens[i]));
                q.add(node.right);
            }
            i++;
        }
        return root;
    }

    public static void main(String[] args) throws IOException {
        String[] data = new String(System.in.readAllBytes()).trim().split("\\s+");
        long target = Long.parseLong(data[data.length - 1]);
        TreeNode root = build(data, data.length - 1);
        System.out.println(hasPathSum(root, target) ? "true" : "false");
    }
