def gen(rng):
    def shape(n, mode):
        L = [-1] * n
        R = [-1] * n
        if mode == 'left':
            for i in range(1, n):
                L[i - 1] = i
        elif mode == 'right':
            for i in range(1, n):
                R[i - 1] = i
        elif mode == 'zig':
            for i in range(1, n):
                if i % 2:
                    L[i - 1] = i
                else:
                    R[i - 1] = i
        elif mode == 'complete':
            for i in range(n):
                if 2 * i + 1 < n:
                    L[i] = 2 * i + 1
                if 2 * i + 2 < n:
                    R[i] = 2 * i + 2
        else:
            slots = [(0, 0), (0, 1)]
            for i in range(1, n):
                k = rng.randrange(len(slots))
                slots[k], slots[-1] = slots[-1], slots[k]
                p, s = slots.pop()
                if s == 0:
                    L[p] = i
                else:
                    R[p] = i
                slots.append((i, 0))
                slots.append((i, 1))
        return L, R

    def ser(L, R, vals):
        out = []
        q = [0]
        qi = 0
        while qi < len(q):
            u = q[qi]
            qi += 1
            if u < 0:
                out.append('null')
                continue
            out.append(str(vals[u]))
            q.append(L[u])
            q.append(R[u])
        while out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    def make(n, mode, vlo, vhi, kind):
        L, R = shape(n, mode)
        vals = [rng.randint(vlo, vhi) for _ in range(n)]
        s = [0] * n
        s[0] = vals[0]
        leaf_sums = []
        inner_sums = []
        st = [0]
        while st:
            u = st.pop()
            if L[u] < 0 and R[u] < 0:
                leaf_sums.append(s[u])
            else:
                if u != 0:
                    inner_sums.append(s[u])
                for c in (L[u], R[u]):
                    if c >= 0:
                        s[c] = s[u] + vals[c]
                        st.append(c)
        if kind == 'leaf':
            target = rng.choice(leaf_sums)
        elif kind == 'inner' and inner_sums:
            target = rng.choice(inner_sums)
        elif kind == 'root':
            target = vals[0]
        elif kind == 'near':
            target = rng.choice(leaf_sums) + rng.choice([-1, 1])
        else:
            target = rng.randint(-20, 20)
        return ser(L, R, vals) + '\n' + str(target)

    tests = [
        '7\n7', '7\n8', '-3\n-3', '1 2\n3', '1 2\n1', '1 null 2\n3', '1 2 3\n4', '1 2 3\n1',
        '1 2 3 4 5\n7', '5 -2 null 3\n6', '5 -2 null 3\n3',
    ]
    for _ in range(40):
        n = rng.randint(1, 15)
        mode = rng.choice(['random', 'random', 'left', 'right', 'zig', 'complete'])
        kind = rng.choice(['leaf', 'leaf', 'inner', 'root', 'near', 'rand'])
        tests.append(make(n, mode, -9, 9, kind))
    N = 100000
    tests.append(make(N, 'random', -10**4, 10**4, 'leaf'))
    tests.append(make(N, 'left', -10**4, 10**4, 'near'))
    tests.append(make(N, 'zig', -10**4, 10**4, 'leaf'))
    tests.append(make(N, 'complete', -10**4, 10**4, 'leaf'))
    tests.append(make(N, 'right', 1, 3, 'inner'))
    return tests
